"use client";

import { useAgentStore } from '@/lib/store/agent-store';
import { X, Terminal, ChevronUp, ChevronDown, Activity, Trash2 } from 'lucide-react';
import { useEffect, useRef } from 'react';

export function AgentDebugOverlay() {
  const { logs, isOverlayOpen, toggleOverlay, clearLogs } = useAgentStore();
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOverlayOpen && bottomRef.current) {
      bottomRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [logs, isOverlayOpen]);

  if (!isOverlayOpen) {
    return (
      <button
        onClick={toggleOverlay}
        className="fixed bottom-4 right-4 bg-gray-900 text-white p-3 rounded-full shadow-lg hover:bg-gray-800 transition-all z-50 ring-2 ring-primary/50"
      >
        <Activity className="w-6 h-6 animate-pulse" />
      </button>
    );
  }

  return (
    <div className="fixed bottom-4 right-4 w-[600px] max-w-[90vw] bg-gray-900/95 backdrop-blur-md rounded-lg shadow-2xl border border-gray-700 z-50 flex flex-col overflow-hidden font-mono text-xs transition-all duration-300">
      {/* Header */}
      <div className="flex items-center justify-between p-3 border-b border-gray-800 bg-gray-950/50">
        <div className="flex items-center gap-2 text-primary font-bold">
          <Terminal className="w-4 h-4" />
          <span>AGENT NEURAL LINK</span>
        </div>
        <div className="flex items-center gap-2">
           <button onClick={clearLogs} className="text-gray-500 hover:text-red-400 p-1">
            <Trash2 className="w-4 h-4" />
          </button>
          <button onClick={toggleOverlay} className="text-gray-400 hover:text-white p-1">
            <ChevronDown className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Logs Area */}
      <div className="flex-1 h-[400px] overflow-y-auto p-4 space-y-2 scrollbar-thin scrollbar-thumb-gray-700 scrollbar-track-transparent">
        {logs.length === 0 && (
          <div className="text-gray-600 italic text-center mt-20">
            Scanning for agent activity...
          </div>
        )}
        {logs.map((log) => (
          <div key={log.id} className="flex gap-3 group animate-in fade-in slide-in-from-bottom-2 duration-300">
            <span className="text-gray-500 min-w-[60px]">{log.timestamp}</span>
            <div className="flex-1 break-words">
              <span className={`font-bold mr-2 ${getSourceColor(log.source)}`}>
                [{log.source}]
              </span>
              <span className={`${getTypeColor(log.type)}`}>
                {log.message}
              </span>
              {log.details && (
                <pre className="mt-1 text-[10px] text-gray-500 bg-black/30 p-2 rounded overflow-x-auto">
                  {JSON.stringify(log.details, null, 2)}
                </pre>
              )}
            </div>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>
    </div>
  );
}

function getSourceColor(source: string) {
  switch (source) {
    case 'ORCHESTRATOR': return 'text-purple-400';
    case 'DISCOVERY': return 'text-blue-400';
    case 'TRANSACTION': return 'text-green-400';
    case 'NETWORK': return 'text-yellow-400';
    default: return 'text-gray-400';
  }
}

function getTypeColor(type: string) {
  switch (type) {
    case 'error': return 'text-red-400';
    case 'success': return 'text-green-300';
    case 'warning': return 'text-yellow-300';
    default: return 'text-gray-300';
  }
}
